PAPER02_U4_U5_QUESTIONS = [{'id': 61, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': 'In which year did the British National Bibliography (BNB) begin its regular publication, and what is its standard periodicity?', 'q_hi': "'ब्रिटिश नेशनल बिब्लियोग्राफी' (BNB) ने अपना नियमित प्रकाशन किस वर्ष प्रारंभ किया और इसकी मानक आवधिकता (Periodicity) क्या है?", 'options_en': ['1947, Monthly', '1950, Weekly', '1954, Fortnightly', '1958, Quarterly'], 'options_hi': ['1947, मासिक', '1950, साप्ताहिक', '1954, पाक्षिक', '1958, त्रैमासिक'], 'answer': 'B', 'exp_en': 'The British National Bibliography (BNB) commenced publication on 4 January 1950. It is issued on a weekly basis with interim cumulations and annual volumes, recording the publishing output of the United Kingdom and Ireland arranged according to the Dewey Decimal Classification (DDC).', 'exp_hi': 'ब्रिटिश नेशनल बिब्लियोग्राफी (BNB) का प्रकाशन 4 जनवरी 1950 को शुरू हुआ था। यह साप्ताहिक (Weekly) रूप से प्रकाशित होती है और यूनाइटेड किंगडम तथा आयरलैंड में प्रकाशित पुस्तकों का राष्ट्रीय रिकॉर्ड है, जिसे DDC के अनुसार व्यवस्थित किया जाता है।'}, {'id': 62, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': 'In the Indian National Bibliography (INB), how are bibliographic entries organized in the main Classified Section?', 'q_hi': "भारतीय राष्ट्रीय ग्रंथसूची (INB) के मुख्य 'वर्गीकृत अनुभाग' (Classified Section) में ग्रंथपरक प्रविष्टियों को किस वर्गीकरण पद्धति के अनुसार व्यवस्थित किया जाता है?", 'options_en': ['Colon Classification (6th Edition)', 'Library of Congress Classification', 'Dewey Decimal Classification (DDC)', 'Universal Decimal Classification (UDC)'], 'options_hi': ['कोलन वर्गीकरण (छठा संस्करण)', 'लाइब्रेरी ऑफ कांग्रेस वर्गीकरण', 'डेवी दशमलव वर्गीकरण (DDC)', 'यूनिवर्सल दशमलव वर्गीकरण (UDC)'], 'answer': 'C', 'exp_en': 'Entries in the Classified Section of the Indian National Bibliography (INB) are systematically arranged according to the Dewey Decimal Classification (DDC) scheme, while Colon Classification (CC) class numbers are also assigned and printed on the bottom right of each entry for reference.', 'exp_hi': 'भारतीय राष्ट्रीय ग्रंथसूची (INB) के मुख्य वर्गीकृत भाग में प्रविष्टियों को डेवी दशमलव वर्गीकरण (DDC) पद्धति के अनुसार क्रमबद्ध किया जाता है, यद्यपि पाठकों के संदर्भ हेतु प्रत्येक प्रविष्टि के नीचे कोलन वर्गीकरण (CC) संख्या भी दी जाती है।'}, {'id': 63, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "'Guide to Indian Periodical Literature' (GIPL), an indispensable quarterly indexing service covering social sciences and humanities in India, is published by:", 'q_hi': "भारत में सामाजिक विज्ञान एवं मानविकी को कवर करने वाली अनिवार्य त्रैमासिक अनुक्रमणिका सेवा 'गाइड टू इंडियन पीरियोडिकल लिटरेचर' (GIPL) किसके द्वारा प्रकाशित की जाती है?", 'options_en': ['Prabhu Book Service, Gurugram', 'Indian Council of Social Science Research (ICSSR), New Delhi', 'National Library of India, Kolkata', 'CSIR-NIScPR, New Delhi'], 'options_hi': ['प्रभु बुक सर्विस, गुरुग्राम (हरियाणा)', 'भारतीय सामाजिक विज्ञान अनुसंधान परिषद (ICSSR), नई दिल्ली', 'राष्ट्रीय पुस्तकालय, कोलकाता', 'सीएसआईआर-निस्पर (CSIR-NIScPR), नई दिल्ली'], 'answer': 'A', 'exp_en': 'Guide to Indian Periodical Literature (GIPL) was founded in 1964 and is published quarterly (with annual cumulations) by Prabhu Book Service, Gurugram. It indexes articles, research papers, book reviews, and creative writings from over 300 Indian journals in social sciences and humanities.', 'exp_hi': "'गाइड टू इंडियन पीरियोडिकल लिटरेचर' (GIPL) की शुरुआत 1964 में हुई थी और यह प्रभु बुक सर्विस, गुरुग्राम (हरियाणा) द्वारा त्रैमासिक रूप से प्रकाशित की जाती है, जो भारत के 300 से अधिक सामाजिक विज्ञान व मानविकी जर्नलों का विषय एवं लेखक अनुक्रमण करती है।"}, {'id': 64, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "'Indian Science Abstracts' (ISA), a major national abstracting service indexing scientific research papers published in India, was started in 1965 by which organization?", 'q_hi': "भारत में प्रकाशित वैज्ञानिक शोध पत्रों को सूचीबद्ध करने वाली प्रमुख राष्ट्रीय सारकरण पत्रिका 'इंडियन साइंस एब्सट्रैक्ट्स' (ISA) 1965 में किस संस्था द्वारा प्रारंभ की गई थी?", 'options_en': ['DRTC, Bangalore', 'INSDOC (now CSIR-NIScPR), New Delhi', 'Bhabha Atomic Research Centre (BARC), Mumbai', 'Indian National Science Academy (INSA), New Delhi'], 'options_hi': ['डीआरटीसी (DRTC), बैंगलोर', 'इन्सडॉक (अब CSIR-NIScPR), नई दिल्ली', 'भाभा परमाणु अनुसंधान केंद्र (BARC), मुंबई', 'भारतीय राष्ट्रीय विज्ञान अकादमी (INSA), नई दिल्ली'], 'answer': 'B', 'exp_en': 'Indian Science Abstracts (ISA) was launched in January 1965 by the Indian National Scientific Documentation Centre (INSDOC), which later became NISCAIR (now CSIR-NIScPR). It abstracts and indexes original scientific research work published in Indian journals, conference proceedings, and patents.', 'exp_hi': 'इंडियन साइंस एब्सट्रैक्ट्स (ISA) की शुरुआत जनवरी 1965 में इन्सडॉक (INSDOC, जो बाद में NISCAIR और वर्तमान में CSIR-NIScPR बना) द्वारा की गई थी। यह भारतीय पत्रिकाओं, सम्मेलनों और पेटेंटों में प्रकाशित संपूर्ण वैज्ञानिक शोध कार्य का सार प्रस्तुत करती है।'}, {'id': 65, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "'Biological Abstracts', one of the world's most comprehensive abstracting periodicals for the life sciences, was initiated in 1926 by:", 'q_hi': "जीव विज्ञान के क्षेत्र में विश्व की सबसे व्यापक सारकरण पत्रिकाओं में से एक 'बायोलॉजिकल एब्सट्रैक्ट्स' (Biological Abstracts) 1926 में किसके द्वारा शुरू की गई थी?", 'options_en': ['American Medical Association (AMA)', 'BioSciences Information Service (BIOSIS)', 'Royal Society of Biology, London', 'National Library of Medicine (NLM), USA'], 'options_hi': ['अमेरिकन मेडिकल एसोसिएशन (AMA)', 'बायोसाइंसेज इंफॉर्मेशन सर्विस (BIOSIS)', 'रॉयल सोसाइटी ऑफ बायोलॉजी, लंदन', 'नेशनल लाइब्रेरी ऑफ मेडिसिन (NLM), यूएसए'], 'answer': 'B', 'exp_en': "Biological Abstracts was founded in 1926 by BIOSIS (BioSciences Information Service) through the union of 'Abstracts of Bacteriology' and 'Botanical Abstracts'. It covers peer-reviewed life sciences and biomedical research literature globally.", 'exp_hi': "बायोलॉजिकल एब्सट्रैक्ट्स की स्थापना 1926 में बायोसाइंसेज इंफॉर्मेशन सर्विस (BIOSIS) द्वारा 'एब्सट्रैक्ट्स ऑफ बैक्टीरियोलॉजी' और 'बॉटनिकल एब्सट्रैक्ट्स' के विलय से की गई थी। यह जीव विज्ञान और जैव चिकित्सा के क्षेत्र में विश्वभर के शोध साहित्य का व्यापक सार प्रदान करती है।"}, {'id': 66, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "The landmark American reference bibliography 'Guide to Reference Books' was first compiled in 1902 by Alice Bertha Kroeger and later famously edited by Constance Winchell and Eugene Sheehy. It is published by:", 'q_hi': "ऐतिहासिक अमेरिकी संदर्भ ग्रंथसूची 'गाइड टू रेफरेंस बुक्स' (Guide to Reference Books) पहली बार 1902 में एलिस बर्था क्रोगर द्वारा संकलित की गई थी और बाद में कॉन्स्टेंस विंचेस और यूजीन शीही द्वारा संपादित की गई। यह किसके द्वारा प्रकाशित की जाती है?", 'options_en': ['Library of Congress', 'American Library Association (ALA)', 'R.R. Bowker', 'H.W. Wilson Company'], 'options_hi': ['लाइब्रेरी ऑफ कांग्रेस', 'अमेरिकन लाइब्रेरी एसोसिएशन (ALA)', 'आर. आर. बाउकर', 'एच. डब्ल्यू. विल्सन कंपनी'], 'answer': 'B', 'exp_en': '\'Guide to Reference Books\' is a premier tertiary reference guide published by the American Library Association (ALA). It evolved through successive editions edited by Isadore Gilbert Mudge, Constance M. Winchell (7th & 8th eds, widely cited as "Winchell"), Eugene P. Sheehy (9th & 10th eds), and Robert Balay (11th ed, 1996).', 'exp_hi': "'गाइड टू रेफरेंस बुक्स' अमेरिकन लाइब्रेरी एसोसिएशन (ALA) द्वारा प्रकाशित एक अत्यंत प्रतिष्ठित तृतीयक संदर्भ स्रोत है। इसके प्रसिद्ध संस्करणों का संपादन इसाडोर गिलबर्ट मज, कॉन्स्टेंस एम. विंचेस ('विंचेस') और यूजीन पी. शीही ने किया था।"}, {'id': 67, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "'Walford's Guide to Reference Material', the British counterpart to the Guide to Reference Books covering global reference literature across three volumes, was compiled by A.J. Walford and published by:", 'q_hi': "'गाइड टू रेफरेंस बुक्स' का ब्रिटिश समकक्ष तीन खंडों में वैश्विक संदर्भ साहित्य को कवर करने वाला 'वाल्फोर्ड्स गाइड टू रेफरेंस मैटेरियल' ए. जे. वाल्फोर्ड द्वारा संकलित एवं किसके द्वारा प्रकाशित किया गया था?", 'options_en': ['British Museum', 'The Library Association (now CILIP), London', 'Oxford University Press', 'ASLIB'], 'options_hi': ['ब्रिटिश म्यूजियम', 'द लाइब्रेरी एसोसिएशन (अब CILIP), लंदन', 'ऑक्सफोर्ड यूनिवर्सिटी प्रेस', 'एस्लिब (ASLIB)'], 'answer': 'B', 'exp_en': "Walford's Guide to Reference Material was first published in 1959 by The Library Association (now CILIP), London. Compiled by Arthur John Walford, it is organized across three thematic subject volumes (Science & Technology; Social & Historical Sciences; Generalia & Humanities) as a classic tertiary guide.", 'exp_hi': 'वाल्फोर्ड्स गाइड टू रेफरेंस मैटेरियल पहली बार 1959 में द लाइब्रेरी एसोसिएशन (वर्तमान में CILIP), लंदन द्वारा प्रकाशित हुआ था। डॉ. ए. जे. वाल्फोर्ड द्वारा संकलित यह ग्रंथ तीन खंडों में प्रमुख संदर्भ स्रोतों की आलोचनात्मक निर्देशिका है।'}, {'id': 68, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "The 'Universities Handbook', an authoritative biennial directory providing comprehensive details on university governance, faculties, courses, and affiliated colleges across India, is published by:", 'q_hi': "भारत भर के विश्वविद्यालयों के प्रशासन, संकायों, पाठ्यक्रमों और संबद्ध कॉलेजों का व्यापक विवरण देने वाली प्रामाणिक निर्देशिका 'यूनिवर्सिटीज हैंडबुक' किसके द्वारा प्रकाशित की जाती है?", 'options_en': ['University Grants Commission (UGC), New Delhi', 'Association of Indian Universities (AIU), New Delhi', 'National Council of Educational Research and Training (NCERT)', 'National Assessment and Accreditation Council (NAAC)'], 'options_hi': ['विश्वविद्यालय अनुदान आयोग (UGC), नई दिल्ली', 'भारतीय विश्वविद्यालय संघ (AIU), नई दिल्ली', 'एनसीईआरटी (NCERT)', 'नैक (NAAC), बैंगलोर'], 'answer': 'B', 'exp_en': 'The Universities Handbook is an authoritative directory published periodically (traditionally biennially) by the Association of Indian Universities (AIU), New Delhi (formerly Inter-University Board of India). It details all recognized universities, institutes of national importance, and deemed universities.', 'exp_hi': "'यूनिवर्सिटीज हैंडबुक' भारतीय विश्वविद्यालय संघ (AIU, Association of Indian Universities), नई दिल्ली द्वारा प्रकाशित की जाने वाली एक अत्यंत प्रामाणिक निर्देशिका (Tertiary Directory) है, जिसमें भारत के सभी विश्वविद्यालयों, डीम्ड विश्वविद्यालयों और राष्ट्रीय महत्व के संस्थानों का पूर्ण विवरण होता है।"}, {'id': 69, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "The concept of the 'Technological Gatekeeper'—an informal human information link in R&D organizations who reads widely and channels external technical knowledge to colleagues—was conceptualized by:", 'q_hi': "अनुसंधान एवं विकास (R&D) संगठनों में अनौपचारिक मानव सूचना लिंक 'टेक्नोलॉजिकल गेटकीपर' (Technological Gatekeeper) की अवधारणा किसने प्रतिपादित की थी, जो बाह्य तकनीकी ज्ञान को सहकर्मियों तक पहुंचाता है?", 'options_en': ['Thomas J. Allen', 'F.W. Lancaster', 'Derek J. de Solla Price', 'B.C. Vickery'], 'options_hi': ['थॉमस जे. एलन (Thomas J. Allen)', 'एफ. डब्ल्यू. लैंकेस्टर', 'डेरेक जे. डी सोला प्राइस', 'बी. सी. विकरी'], 'answer': 'A', 'exp_en': "Thomas J. Allen of MIT introduced the concept of the 'Technological Gatekeeper' in 1977 in his seminal work 'Managing the Flow of Technology'. Gatekeepers act as vital human channels for translating and transferring external scientific literature and technology into an organization.", 'exp_hi': "एमआईटी के प्रोफेसर थॉमस जे. एलन ने 1977 में 'मैनेजिंग द फ्लो ऑफ टेक्नोलॉजी' में 'टेक्नोलॉजिकल गेटकीपर' की अवधारणा दी। ये संगठन के वे प्रमुख व्यक्ति होते हैं जो बाहरी उन्नत तकनीकी सूचनाओं को स्वयं पढ़कर आंतरिक सहयोगियों तक सरल भाषा में पहुँचाते हैं।"}, {'id': 70, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "Who popularized the term 'Invisible College' in information science to describe informal, elite communication networks and citation clusters among pioneering research scientists?", 'q_hi': "अग्रणी शोध वैज्ञानिकों के बीच अनौपचारिक संचार नेटवर्क और उद्धरण समूहों का वर्णन करने हेतु सूचना विज्ञान में 'अदृश्य कॉलेज' (Invisible College) शब्द को किसने लोकप्रिय बनाया था?", 'options_en': ['Eugene Garfield', 'Derek J. de Solla Price', 'S.R. Ranganathan', 'Robert K. Merton'], 'options_hi': ['यूजीन गारफील्ड', 'डेरेक जे. डी सोला प्राइस (Derek J. de Solla Price)', 'एस. आर. रंगनाथन', 'रॉबर्ट के. मर्टन'], 'answer': 'B', 'exp_en': "Derek J. de Solla Price popularized the concept of 'Invisible Colleges' in his 1963 landmark book 'Little Science, Big Science'. It refers to informal scientific communication networks where specialists share preprints and ideas before formal publication.", 'exp_hi': "डेरेक जे. डी सोला प्राइस ने अपनी 1963 की प्रसिद्ध पुस्तक 'लिटिल साइंस, बिग साइंस' में 'अदृश्य कॉलेज' (Invisible College) की अवधारणा दी। यह वैज्ञानिकों और शोधकर्ताओं के उस अनौपचारिक समूह को दर्शाता है जो औपचारिक प्रकाशन से पूर्व आपस में पत्रों, ड्राफ्ट्स और विचारों का आदान-प्रदान करते हैं।"}, {'id': 71, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "What is the fundamental functional characteristic that distinguishes a 'Referral Centre' from an ordinary library reference department?", 'q_hi': "एक 'रेफरल केंद्र' (Referral Centre) को एक सामान्य पुस्तकालय संदर्भ विभाग से अलग करने वाली मूलभूत कार्यात्मक विशेषता क्या है?", 'options_en': ['It lends printed books directly to registered home borrowers', 'It does not supply direct answers or documents, but directs the enquirer to appropriate specialized agencies or human experts', 'It only provides automated photocopying services', 'It is restricted solely to the accessioning and binding of government reports'], 'options_hi': ['यह पंजीकृत पाठकों को सीधे घर ले जाने हेतु पुस्तकें उधार देता है', 'यह सीधे उत्तर या प्रलेख नहीं देता, बल्कि पूछताछकर्ता को उपयुक्त विशेषज्ञ संस्थाओं या मानव विशेषज्ञों के पास निर्देशित करता है', 'यह केवल स्वचालित फोटोकॉपी सेवाएं प्रदान करता है', 'यह केवल सरकारी रिपोर्टों के परिग्रहण और जिल्दसाजी तक सीमित है'], 'answer': 'B', 'exp_en': 'A Referral Centre functions as an institutional guidepost that does not directly answer factual queries or supply literature, but directs (refers) the user to specialized external sources, organizations, data banks, or individual experts holding the required knowledge.', 'exp_hi': 'रेफरल केंद्र (Referral Centre) स्वयं सूचना प्रलेख या सीधा तथ्यात्मक उत्तर प्रदान नहीं करता, बल्कि सूचना चाहने वाले को उस विशिष्ट स्रोत, संस्था या विषय-विशेषज्ञ (Human Expert) का पता व संदर्भ देता है जहाँ से सूचना प्राप्त हो सकती है।'}, {'id': 72, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "In virtual reference services, which of the following is classified as a 'Synchronous' reference interaction?", 'q_hi': "आभासी संदर्भ सेवाओं (Virtual Reference Services) में निम्नलिखित में से किसे 'तुल्यकालिक' (Synchronous / रीयल-टाइम) संदर्भ संवाद के रूप में वर्गीकृत किया जाता है?", 'options_en': ['Web-form enquiry submission', 'Email-based reference service', 'Live Web Chat reference', 'Offline postal query'], 'options_hi': ['वेब-फॉर्म के माध्यम से पूछताछ भेजना', 'ईमेल आधारित संदर्भ सेवा', 'लाइव वेब चैट संदर्भ सेवा (Live Web Chat Reference)', 'ऑफलाइन डाक द्वारा पूछताछ'], 'answer': 'C', 'exp_en': 'Synchronous virtual reference takes place in real time with immediate, two-way communication (e.g., Live Chat reference, video conferencing, instant messaging). In contrast, email and web forms are asynchronous where query submission and answering are separated by a time delay.', 'exp_hi': "तुल्यकालिक (Synchronous) संदर्भ सेवा वास्तविक समय (Real-time) में तात्कालिक संवाद प्रदान करती है, जैसे लाइव वेब चैट (Chat Reference) या वीडियो कॉल। इसके विपरीत ईमेल या वेब-फॉर्म 'अतुल्यकालिक' (Asynchronous) होते हैं जिनमें उत्तर कुछ समय बाद मिलता है।"}, {'id': 73, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': 'The Collaborative Digital Reference Service (CDRS), launched in 2000 to harness the worldwide collective expertise of reference librarians 24/7, was initiated by:', 'q_hi': "दुनिया भर के संदर्भ पुस्तकालयाध्यक्षों की सामूहिक विशेषज्ञता को 24x7 उपयोग करने हेतु वर्ष 2000 में शुरू की गई 'सहयोगात्मक डिजिटल संदर्भ सेवा' (CDRS) किसके द्वारा प्रारंभ की गई थी?", 'options_en': ['British Library', 'Library of Congress (USA)', 'UNESCO Information Division', 'IFLA Headquarters'], 'options_hi': ['ब्रिटिश लाइब्रेरी', 'लाइब्रेरी ऑफ कांग्रेस (यूएसए)', 'यूनेस्को सूचना प्रभाग', 'इफ़्ला (IFLA) मुख्यालय'], 'answer': 'B', 'exp_en': "The Collaborative Digital Reference Service (CDRS) was launched in early 2000 by the Library of Congress. In 2002, the Library of Congress partnered with OCLC to transition CDRS into the widely recognized cooperative virtual reference platform named 'QuestionPoint'.", 'exp_hi': "सहयोगात्मक डिजिटल संदर्भ सेवा (CDRS) को 2000 में लाइब्रेरी ऑफ कांग्रेस द्वारा प्रारंभ किया गया था। बाद में 2002 में लाइब्रेरी ऑफ कांग्रेस ने ओसीएलसी (OCLC) के साथ मिलकर इसे 'क्वेश्चनपॉइंट' (QuestionPoint) के रूप में वैश्विक स्तर पर 24/7 संदर्भ सेवा हेतु विस्तारित किया।"}, {'id': 74, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "In India, the 'National Index of Translations' (NIT), serving as a national clearinghouse to avoid duplication of scientific translation efforts from foreign languages into English, was maintained by:", 'q_hi': "भारत में विदेशी भाषाओं से अंग्रेजी में किए गए वैज्ञानिक अनुवादों के दोहराव को रोकने हेतु राष्ट्रीय समाशोधन गृह के रूप में 'नेशनल इंडेक्स ऑफ ट्रांसलेशंस' (NIT) किसके द्वारा अनुरक्षित किया जाता था?", 'options_en': ['National Library of India, Kolkata', 'INSDOC', 'Central Institute of Indian Languages (CIIL), Mysuru', 'Sahitya Akademi, New Delhi'], 'options_hi': ['राष्ट्रीय पुस्तकालय, कोलकाता', 'NISCAIR (now CSIR-NIScPR), New Delhi', 'केंद्रीय भारतीय भाषा संस्थान (CIIL), मैसूरु', 'साहित्य अकादमी, नई दिल्ली'], 'answer': 'B', 'exp_en': 'The National Index of Translations (NIT) was initiated and maintained by INSDOC (later NISCAIR / CSIR-NIScPR) from 1981 onwards. It maintained records of scientific and technical papers translated into English from Russian, German, French, Japanese, etc., in Indian institutions.', 'exp_hi': 'नेशनल इंडेक्स ऑफ ट्रांसलेशंस (NIT) का संधारण इन्सडॉक (बाद में निस्केयर / CSIR-NIScPR) द्वारा 1981 से किया जाता रहा है, ताकि रूसी, जर्मन, जापानी आदि भाषाओं से अंग्रेजी में हुए वैज्ञानिक अनुवादों का राष्ट्रीय रिकॉर्ड रखा जा सके और अनुवाद के दोहरे श्रम से बचा जा सके।'}, {'id': 75, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "On the recommendation of the National Knowledge Commission (NKC), the 'National Translation Mission' (NTM) was set up by the Government of India with its headquarters located at:", 'q_hi': "राष्ट्रीय ज्ञान आयोग (NKC) की सिफारिश पर भारत सरकार द्वारा 'राष्ट्रीय अनुवाद मिशन' (NTM) की स्थापना की गई, जिसका मुख्यालय कहाँ स्थित है?", 'options_en': ['Central Institute of Indian Languages (CIIL), Mysuru', 'National Book Trust (NBT), New Delhi', 'English and Foreign Languages University (EFLU), Hyderabad', 'Rashtriya Sanskrit Sansthan, New Delhi'], 'options_hi': ['केंद्रीय भारतीय भाषा संस्थान (CIIL), मैसूरु', 'नेशनल बुक ट्रस्ट (NBT), नई दिल्ली', 'ईएफ़एलयू (EFLU), हैदराबाद', 'राष्ट्रीय संस्कृत संस्थान, नई दिल्ली'], 'answer': 'A', 'exp_en': 'The National Translation Mission (NTM) was established under the Ministry of Education following recommendations of the National Knowledge Commission. Headquartered at the Central Institute of Indian Languages (CIIL), Mysuru, its mandate is to translate higher education knowledge texts into the 22 Scheduled Indian languages.', 'exp_hi': 'राष्ट्रीय अनुवाद मिशन (NTM) की स्थापना राष्ट्रीय ज्ञान आयोग (NKC) की सिफारिशों पर मानव संसाधन विकास मंत्रालय द्वारा की गई थी। यह केंद्रीय भारतीय भाषा संस्थान (CIIL), मैसूरु में स्थित है और इसका मुख्य उद्देश्य उच्च शिक्षा की मानक पाठ्यपुस्तकों का संविधान की 8वीं अनुसूची की 22 भाषाओं में अनुवाद करना है।'}, {'id': 76, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': 'The INDEST (Indian National Digital Library in Engineering Sciences and Technology) Consortium was established in 2003 by the Ministry of HRD with its operational headquarters hosted at:', 'q_hi': "मानव संसाधन विकास मंत्रालय द्वारा वर्ष 2003 में स्थापित 'इंडेस्ट' (INDEST) कंसोर्टियम का संचालन मुख्यालय किस संस्थान में स्थापित किया गया था?", 'options_en': ['IIT Bombay', 'IIT Delhi', 'IIT Madras', 'IISc Bangalore'], 'options_hi': ['आईआईटी बॉम्बे', 'आईआईटी दिल्ली (IIT Delhi)', 'आईआईटी मद्रास', 'आईआईएससी बैंगलोर'], 'answer': 'B', 'exp_en': 'The INDEST Consortium was established in 2003 by the Ministry of HRD to provide consortium-based access to electronic journals and databases in engineering, science, and technology. Its consortium headquarters and operational infrastructure was set up at the Indian Institute of Technology (IIT) Delhi.', 'exp_hi': 'इंडेस्ट (INDEST) कंसोर्टियम की स्थापना 2003 में एमएचआरडी द्वारा इंजीनियरिंग, विज्ञान एवं प्रौद्योगिकी संस्थानों को ई-संसाधन सुलभ कराने हेतु की गई थी। इसका संचालन केंद्र व मुख्यालय भारतीय प्रौद्योगिकी संस्थान (IIT) दिल्ली में स्थापित किया गया था।'}, {'id': 77, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "'CeRA' (Consortium for e-Resources in Agriculture), providing online access to agricultural journals and literature across Indian state agricultural universities and ICAR institutes, was established in:", 'q_hi': "भारतीय कृषि अनुसंधान परिषद (ICAR) के संस्थानों और राज्य कृषि विश्वविद्यालयों को ऑनलाइन कृषि जर्नल्स सुलभ कराने वाला 'सीरा' (CeRA) कंसोर्टियम किस वर्ष स्थापित किया गया था?", 'options_en': ['1999', '2003', '2007', '2014'], 'options_hi': ['1999', '2003', '2007', '2014'], 'answer': 'C', 'exp_en': 'CeRA (Consortium for e-Resources in Agriculture) was established in November 2007 by the Indian Council of Agricultural Research (ICAR) under the National Agricultural Innovation Project (NAIP). It is hosted and administered at ICAR-IARI (Indian Agricultural Research Institute), New Delhi.', 'exp_hi': "कृषि क्षेत्र में ई-संसाधनों हेतु 'सीरा' (CeRA) कंसोर्टियम की स्थापना नवंबर 2007 में भारतीय कृषि अनुसंधान परिषद (ICAR) द्वारा राष्ट्रीय कृषि नवाचार परियोजना (NAIP) के तहत की गई थी। इसका संचालन आईएआरआई (IARI), नई दिल्ली द्वारा किया जाता है।"}, {'id': 78, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "In December 2015, the Ministry of Education formed 'e-ShodhSindhu: Consortium for Higher Education E-Resources' by merging which three existing consortia?", 'q_hi': "दिसंबर 2015 में शिक्षा मंत्रालय ने किन तीन तत्कालीन कंसोर्टिया का विलय करके 'ई-शोधसिंधु' (e-ShodhSindhu) का गठन किया था?", 'options_en': ['UGC-INFONET, N-LIST, and INDEST-AICTE', 'CeRA, DELNET, and ERNET', 'FORSA, CSIR e-Journal Consortium, and MCIT', 'CALIBNET, MALIBNET, and BONET'], 'options_hi': ['यूजीसी-इन्फोनेट, एन-लिस्ट (N-LIST) और इंडेस्ट-एआईसीटीई (INDEST-AICTE)', 'सीरा, डेलनेट और एरनेट', 'फोर्सा, सीएसआईआर और एमसीआईटी', 'कैलिबनेट, मैलिबनेट और बोनेट'], 'answer': 'A', 'exp_en': 'e-ShodhSindhu was formed in December 2015 by the Ministry of HRD by merging three major consortia: UGC-INFONET Digital Library Consortium, N-LIST, and INDEST-AICTE Consortium. It is executed and operated by the INFLIBNET Centre, Gandhinagar.', 'exp_hi': 'ई-शोधसिंधु का गठन दिसंबर 2015 में तीन प्रमुख कंसोर्टिया—UGC-INFONET, N-LIST, तथा INDEST-AICTE—को आपस में मिलाकर किया गया था। इसका क्रियान्वयन एवं प्रबंधन इन्फ्लिबनेट केंद्र, गांधीनगर द्वारा किया जाता है।'}, {'id': 79, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': "If a researcher has published 20 papers, and 12 of those papers have received at least 12 citations each, what is the 'h-index' of the researcher according to the metric developed by Jorge E. Hirsch in 2005?", 'q_hi': "यदि किसी शोधकर्ता ने 20 शोध पत्र प्रकाशित किए हैं, और उनमें से 12 शोध पत्रों को कम से कम 12 या उससे अधिक उद्धरण (Citations) प्राप्त हुए हैं, तो 2005 में जॉर्ज ई. हिर्श द्वारा विकसित मीट्रिक के अनुसार उस शोधकर्ता का 'एच-इंडेक्स' (h-index) क्या होगा?", 'options_en': ['20', '12', '240', '8'], 'options_hi': ['20', '12', '240', '8'], 'answer': 'B', 'exp_en': 'Formulated in 2005 by physicist Jorge E. Hirsch, a scientist has index h if h of his or her N papers have at least h citations each, and the other papers have $\\le h$ citations each. Here, having 12 papers with $\\ge 12$ citations yields an h-index of 12.', 'exp_hi': "भौतिक विज्ञानी जॉर्ज ई. हिर्श (2005) के अनुसार, किसी वैज्ञानिक का एच-इंडेक्स 'h' तब होता है जब उसके कम से कम 'h' शोध पत्रों को न्यूनतम 'h' या उससे अधिक बार उद्धृत किया गया हो। अतः यहाँ 12 शोध पत्रों को 12 या अधिक उद्धरण मिलने पर एच-इंडेक्स 12 होगा।"}, {'id': 80, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 4: Information Sources & Reference Services', 'unit_hi': 'इकाई 4: सूचना स्रोत एवं संदर्भ सेवाएं', 'q_en': 'Which of the following statements regarding citation metrics and Open Access platforms is INCORRECT?', 'q_hi': 'उद्धरण मेट्रिक्स और ओपन एक्सेस प्लेटफॉर्म के संबंध में निम्नलिखित में से कौन-सा कथन असत्य (INCORRECT) है?', 'options_en': ['The g-index was proposed by Leo Egghe in 2006 to give more weight to highly-cited papers', 'The i10-index was introduced by Google Scholar in 2011 to measure the number of publications with at least 10 citations', 'arXiv was created in 1991 by Paul Ginsparg as an open-access preprint repository for physics and related sciences', 'The Directory of Open Access Journals (DOAJ) was established in 1974 by the Library of Congress'], 'options_hi': ['उच्च उद्धृत शोध पत्रों को अधिक भार देने हेतु 2006 में लियो एग्घे (Leo Egghe) द्वारा जी-इंडेक्स प्रस्तावित किया गया था', 'गूगल स्कॉलर ने कम से कम 10 उद्धरण वाले प्रकाशनों की संख्या मापने हेतु 2011 में i10-इंडेक्स शुरू किया था', 'पॉल गिन्सपर्ग ने 1991 में भौतिकी एवं संबंधित विज्ञानों के ओपन एक्सेस प्री-प्रिंट रिपॉजिटरी के रूप में arXiv बनाया था', 'डायरेक्टरी ऑफ ओपन एक्सेस जर्नल्स (DOAJ) की स्थापना 1974 में लाइब्रेरी ऑफ कांग्रेस द्वारा की गई थी'], 'answer': 'D', 'exp_en': 'Statement D is incorrect because DOAJ was launched in May 2003 at Lund University, Sweden (not 1974 by the Library of Congress). Statements A, B, and C are entirely correct: Leo Egghe introduced the g-index (2006), Google Scholar introduced the i10-index (2011), and Paul Ginsparg launched arXiv at Los Alamos in 1991.', 'exp_hi': 'कथन D असत्य है क्योंकि DOAJ (Directory of Open Access Journals) की शुरुआत मई 2003 में लुंड विश्वविद्यालय (स्वीडन) द्वारा की गई थी (1974 में नहीं)। अन्य सभी कथन (g-index लियो एग्घे 2006, i10-index गूगल स्कॉलर 2011, और arXiv पॉल गिन्सपर्ग 1991) पूर्णतः सत्य हैं।'}, {'id': 81, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'NewGenLib, an enterprise-class open-source Integrated Library Management System developed using Java and PostgreSQL, was created by Verus Solutions Pvt. Ltd. with domain expertise provided by:', 'q_hi': "जावा (Java) और पोस्टग्रेएसक्यूएल (PostgreSQL) पर आधारित ओपन-सोर्स एकीकृत पुस्तकालय प्रबंधन सॉफ्टवेयर 'न्यूजेनलिब' (NewGenLib) वेरुस सॉल्यूशंस द्वारा किसकी डोमेन विशेषज्ञता के सहयोग से विकसित किया गया था?", 'options_en': ['Sarada Ranganathan Endowment for Library Science (SRELS)', 'Kesavan Institute of Information and Knowledge Management (KIIKM)', 'DELNET, New Delhi', 'Raja Rammohun Roy Library Foundation (RRRLF)'], 'options_hi': ['शारदा रंगनाथन एंडोमेंट फॉर लाइब्रेरी साइंस', 'केशवन इंस्टीट्यूट ऑफ इंफॉर्मेशन एंड नॉलेज मैनेजमेंट (KIIKM)', 'डेलनेट (DELNET), नई दिल्ली', 'राजा राममोहन राय लाइब्रेरी फाउंडेशन'], 'answer': 'B', 'exp_en': 'NewGenLib was developed jointly by Verus Solutions Pvt. Ltd. and the Kesavan Institute of Information and Knowledge Management (KIIKM), Hyderabad. Named after B.S. Kesavan (the first National Librarian of Independent India), KIIKM provided the professional library domain expertise. It became open source under GNU GPL in 2008.', 'exp_hi': 'न्यूजेनलिब (NewGenLib) का विकास वेरुस सॉल्यूशंस और केशवन इंस्टीट्यूट ऑफ इंफॉर्मेशन एंड नॉलेज मैनेजमेंट (KIIKM), हैदराबाद द्वारा संयुक्त रूप से किया गया था। भारत के प्रथम राष्ट्रीय पुस्तकालयाध्यक्ष बी. एस. केशवन के नाम पर बने इस संस्थान ने पुस्तकालय डोमेन विशेषज्ञता प्रदान की। इसे 2008 में मुक्त स्रोत (GNU GPL) घोषित किया गया।'}, {'id': 82, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "The open-source integrated library suite 'ABCD' (Automatisación de Bibliotécas y Centros de Documentación), promoted by UNESCO and BIREME, is built upon the database technology of:", 'q_hi': "यूनेस्को (UNESCO) और बिरेम (BIREME) द्वारा प्रवर्तित ओपन-सोर्स एकीकृत पुस्तकालय सॉफ्टवेयर 'एबीसीडी' (ABCD) किस डेटाबेस तकनीक की नींव पर निर्मित है?", 'options_en': ['Oracle Database', 'CDS/ISIS', 'Microsoft SQL Server', 'MongoDB NoSQL'], 'options_hi': ['ओरेकल डेटाबेस', 'सीडीएस/आइसिस (CDS/ISIS)', 'माइक्रोसॉफ्ट एसक्यूएल सर्वर', 'मोंगोडीबी नोएसक्यूएल'], 'answer': 'B', 'exp_en': 'ABCD is an open-source web-based integrated library management system developed under the auspices of UNESCO and BIREME. It is built directly on the CDS/ISIS database technology (WWW-ISIS engine), extending ISIS variable-field bibliographic handling into modern web-based library automation.', 'exp_hi': 'एबीसीडी (ABCD) सॉफ्टवेयर यूनेस्को और बिरेम द्वारा विकसित एक वेब-आधारित ओपन-सोर्स पुस्तकालय स्वचालन प्रणाली है। यह यूनेस्को के पारंपरिक CDS/ISIS डेटाबेस इंजन (WWW-ISIS) पर आधारित है जो विविध लंबाई वाले ग्रंथपरक रिकॉर्ड्स को संभालने में सक्षम है।'}, {'id': 83, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "'Shodhganga', developed and maintained by the INFLIBNET Centre under a mandatory UGC regulation of 2009, serves as the national digital repository for:", 'q_hi': "वर्ष 2009 के अनिवार्य यूजीसी विनियमन के तहत इन्फ्लिबनेट केंद्र द्वारा विकसित और अनुरक्षित 'शोधगंगा' (Shodhganga) किसके राष्ट्रीय डिजिटल भंडार के रूप में कार्य करता है?", 'options_en': ['Undergraduate examination question papers', 'Full-text Electronic Theses and Dissertations (ETDs) submitted to Indian universities', 'Science citation patents and trademarks', 'Annual budgets of academic colleges'], 'options_hi': ['स्नातक परीक्षा के प्रश्न पत्र', 'भारतीय विश्वविद्यालयों में जमा किए गए पूर्ण-पाठ इलेक्ट्रॉनिक शोध प्रबंध (Ph.D. Theses & Dissertations)', 'विज्ञान उद्धरण पेटेंट और ट्रेडमार्क', 'अकादमिक कॉलेजों के वार्षिक बजट'], 'answer': 'B', 'exp_en': 'Shodhganga is the digital repository set up by the INFLIBNET Centre under UGC regulations (2009/2016) for hosting full-text Indian Electronic Theses and Dissertations (ETDs) submitted to universities across India, promoting open access to research.', 'exp_hi': 'शोधगंगा (Shodhganga) इन्फ्लिबनेट केंद्र द्वारा संचालित भारतीय विश्वविद्यालयों के पीएचडी शोध प्रबंधों (Electronic Theses and Dissertations - ETDs) का राष्ट्रीय खुला डिजिटल भंडार है, जिसे यूजीसी के 2009 के नियमों के तहत अनिवार्य बनाया गया था।'}, {'id': 84, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "What is the primary role of INFLIBNET's digital initiative 'Shodhgangotri'?", 'q_hi': "इन्फ्लिबनेट की डिजिटल पहल 'शोधगंगोत्री' (Shodhgangotri) का मुख्य उद्देश्य क्या है?", 'options_en': ['Archiving approved research synopses and research proposals to prevent topic duplication', 'Conducting online UGC NET examinations', 'Providing digital identity cards to university librarians', 'Calculating journal impact factors'], 'options_hi': ['शोध विषयों के दोहराव को रोकने हेतु अनुमोदित शोध रूपरेखाओं (Synopses) और प्रस्तावों को संग्रहीत करना', 'ऑनलाइन यूजीसी नेट परीक्षा आयोजित करना', 'विश्वविद्यालय लाइब्रेरियनों को डिजिटल पहचान पत्र प्रदान करना', 'जर्नलों के इम्पैक्ट फैक्टर की गणना करना'], 'answer': 'A', 'exp_en': 'Under Shodhgangotri, Indian universities deposit approved electronic synopses and research proposals submitted by research scholars for Ph.D. registration. It provides a window into ongoing research and prevents duplication of research topics across universities.', 'exp_hi': 'शोधगंगोत्री (Shodhgangotri) में भारतीय विश्वविद्यालयों में पंजीकृत शोधार्थियों द्वारा प्रस्तुत स्वीकृत शोध प्रस्तावों / रूपरेखाओं (Synopses / Research Proposals) का भंडार है, जिसका मुख्य उद्देश्य देश में एक ही विषय पर शोध के अनावश्यक दोहराव (Duplication of Research) को रोकना है।'}, {'id': 85, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "'Vidwan', an e-governance database initiative designed and maintained by the INFLIBNET Centre, is primarily:", 'q_hi': "इन्फ्लिबनेट केंद्र द्वारा डिजाइन और अनुरक्षित ई-गवर्नेंस डेटाबेस पहल 'विद्वान' (Vidwan) मुख्य रूप से क्या है?", 'options_en': ['An online catalog of rare manuscripts in Sanskrit', 'A premier database of profiles of scientists, researchers, and faculty members working at leading Indian institutions', 'An automated book acquisition module for college libraries', 'A union list of serials subscribed by CSIR laboratories'], 'options_hi': ['संस्कृत की दुर्लभ पांडुलिपियों का ऑनलाइन कैटलॉग', 'प्रमुख भारतीय संस्थानों में कार्यरत वैज्ञानिकों, शोधकर्ताओं और संकाय सदस्यों के प्रोफाइल का प्रमुख डेटाबेस', 'कॉलेज पुस्तकालयों हेतु स्वचालित पुस्तक अर्जन मॉड्यूल', 'सीएसआईआर प्रयोगशालाओं द्वारा ली गई पत्रिकाओं की केंद्रीय सूची'], 'answer': 'B', 'exp_en': 'Vidwan is the premier database of profiles of scientists, researchers, and faculty members working in leading academic institutions and R&D organizations in India. It assigns a unique Vidwan ID and links peer-reviewed publications, funding, and scholarly output.', 'exp_hi': 'विद्वान (Vidwan) भारत के अग्रणी शैक्षणिक संस्थानों और अनुसंधान एवं विकास संगठनों में कार्यरत वैज्ञानिकों, शोधकर्ताओं और प्राध्यापकों के प्रोफाइल का राष्ट्रीय डेटाबेस है। यह शोध विशेषज्ञों की खोज और सहयोगात्मक अनुसंधान को बढ़ावा देता है।'}, {'id': 86, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "'e-PG Pathshala', executed by UGC and INFLIBNET under the National Mission on Education through ICT (NMEICT), is designed to provide:", 'q_hi': "आईसीटी के माध्यम से शिक्षा पर राष्ट्रीय मिशन (NMEICT) के तहत यूजीसी और इन्फ्लिबनेट द्वारा निष्पादित 'ई-पीजी पाठशाला' (e-PG Pathshala) क्या प्रदान करने हेतु बनाई गई है?", 'options_en': ['Interactive curriculum-based high-quality e-content across postgraduate subjects', 'Free physical textbooks delivered by courier to rural colleges', 'Biometric attendance software for university libraries', 'Commercial licensing for proprietary e-books'], 'options_hi': ['स्नातकोत्तर (PG) विषयों में पाठ्यक्रम-आधारित उच्च गुणवत्ता वाली इंटरैक्टिव ई-सामग्री', 'ग्रामीण कॉलेजों को कूरियर द्वारा मुफ्त भौतिक पाठ्यपुस्तकें', 'विश्वविद्यालय पुस्तकालयों हेतु बायोमेट्रिक उपस्थिति सॉफ्टवेयर', 'वाणिज्यिक ई-पुस्तकों के लिए मालिकाना लाइसेंसिंग'], 'answer': 'A', 'exp_en': 'e-PG Pathshala is an initiative of the Ministry of Education executed by UGC and INFLIBNET under NMEICT. It provides open-access, curriculum-based high quality interactive e-content (e-text, video lectures, self-assessment) across over 70 postgraduate disciplines.', 'exp_hi': 'ई-पीजी पाठशाला (e-PG Pathshala) शिक्षा मंत्रालय का एक प्रोजेक्ट है जिसे यूजीसी और इन्फ्लिबनेट द्वारा NMEICT योजना के तहत संचालित किया जाता है। यह 70 से अधिक स्नातकोत्तर (PG) विषयों में 4-चतुर्भुज (टेक्स्ट, वीडियो, संदर्भ, मूल्यांकन) पाठ्यक्रम-आधारित निःशुल्क ई-सामग्री प्रदान करता है।'}, {'id': 87, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "In library automation systems, why is the 'Code 39' (Code 3 of 9) barcode symbology widely favored for printing book accession numbers and patron membership barcodes?", 'q_hi': "पुस्तकालय स्वचालन में पुस्तक परिग्रहण संख्या और पाठक सदस्यता बारकोड छापने हेतु 'कोड 39' (Code 39) बारकोड सिम्बोलॉजी को व्यापक रूप से क्यों पसंद किया जाता है?", 'options_en': ['It can only encode numeric digits from 0 to 9', 'It is a variable-length alphanumeric symbology encoding numbers, uppercase letters, and select punctuation with an asterisk (*) start/stop character', 'It requires radio frequency antennas instead of optical scanners', 'It can store up to 5 megabytes of high-definition video data'], 'options_hi': ['यह केवल 0 से 9 तक के अंकों को एनकोड कर सकती है', 'यह एक परिवर्तनीय लंबाई वाली अल्फ़ान्यूमेरिक प्रणाली है जो अंकों, बड़े अक्षरों और कुछ चिह्नों को एस्टरिस्क (*) स्टार्ट/स्टॉप वर्ण के साथ एनकोड करती है', 'इसके लिए ऑप्टिकल स्कैनर के स्थान पर रेडियो फ्रीक्वेंसी एंटीना की आवश्यकता होती है', 'यह 5 मेगाबाइट तक का हाई-डेफिनिशन वीडियो डेटा संग्रहीत कर सकती है'], 'answer': 'B', 'exp_en': 'Developed in 1974 by Intermec, Code 39 (Code 3 of 9) is a linear alphanumeric symbology encoding 43 characters (0-9, A-Z, and 7 special characters) using an asterisk (*) as start and stop delimiters. Its ability to mix letters and numbers makes it ideal for library accession and call numbers.', 'exp_hi': 'कोड 39 (Code 3 of 9) एक अल्फ़ान्यूमेरिक (Alphanumeric) बारकोड सिम्बोलॉजी है जो 43 वर्णों (0-9, A-Z तथा विशेष चिह्न जैसे -, ., $, /, +, %, स्पेस) को एनकोड कर सकती है। इसमें आरंभ और अंत में तारांकन चिह्न (*) अनिवार्य होता है, जिससे यह पुस्तकालय परिग्रहण संख्याओं हेतु अत्यंत उपयुक्त है।'}, {'id': 88, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'Which high-density linear barcode symbology can encode all 128 characters of the standard ASCII character set natively in compact space, and which symbology is universally printed on commercial published books to represent the ISBN-13?', 'q_hi': 'कौन-सी उच्च घनत्व वाली रैखिक बारकोड सिम्बोलॉजी मानक ASCII वर्ण सेट के सभी 128 वर्णों को एनकोड कर सकती है, और व्यावसायिक रूप से प्रकाशित पुस्तकों पर ISBN-13 का प्रतिनिधित्व करने हेतु कौन-सी सिम्बोलॉजी छपी होती है?', 'options_en': ['Code 128 and EAN-13 respectively', 'UPC-A and Codabar respectively', 'PDF417 and Data Matrix respectively', 'Postnet and Interleaved 2 of 5 respectively'], 'options_hi': ['क्रमशः कोड 128 (Code 128) और ईएएन-13 (EAN-13)', 'क्रमशः यूपीसी-ए और कोडाबार', 'क्रमशः पीडीएफ417 और डेटा मैट्रिक्स', 'क्रमशः पोस्टनेट और इंटरलीव्ड 2 ऑफ 5'], 'answer': 'A', 'exp_en': 'Code 128 is a high-density linear symbology that natively encodes the complete 128 ASCII character set. EAN-13 (European / International Article Number) is the 13-digit retail barcode standard globally used on the back cover of books to encode the ISBN-13.', 'exp_hi': "कोड 128 (Code 128) एक अत्यधिक कुशल रैखिक बारकोड है जो सभी 128 ASCII वर्णों को एनकोड कर सकता है। वहीं व्यावसायिक पुस्तकों पर ISBN-13 को प्रदर्शित करने हेतु अंतरराष्ट्रीय मानक 'EAN-13' (European Article Number) बारकोड का उपयोग किया जाता है।"}, {'id': 89, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'The Quick Response (QR) Code is a 2-dimensional matrix barcode invented in 1994 by Masahiro Hara of which company, and standardized globally under which ISO standard?', 'q_hi': 'क्विक रिस्पांस (QR) कोड एक 2-आयामी मैट्रिक्स बारकोड है जिसका आविष्कार 1994 में किस कंपनी के मासाहिरो हारा द्वारा किया गया था, और यह किस ISO मानक के तहत मानकीकृत है?', 'options_en': ['Sony Corporation, ISO 9001', 'Denso Wave (Japan), ISO/IEC 18004', 'Toshiba, ISO 27001', 'Panasonic, ISO 14001'], 'options_hi': ['सोनी कॉर्पोरेशन, ISO 9001', 'डेंसो वेव (Denso Wave, जापान), ISO/IEC 18004', 'तोशिबा, ISO 27001', 'पैनासोनिक, ISO 14001'], 'answer': 'B', 'exp_en': 'The QR Code was invented in 1994 by Masahiro Hara at the Japanese automotive component company Denso Wave. It is standardized internationally under ISO/IEC 18004 and is capable of fast omnidirectional 360-degree reading and high error correction (up to 30%).', 'exp_hi': "क्यूआर कोड (QR Code) का आविष्कार 1994 में जापान की कंपनी 'डेंसो वेव' (Denso Wave) के इंजीनियर मासाहिरो हारा ने किया था। यह अंतरराष्ट्रीय मानक ISO/IEC 18004 के तहत प्रमाणित है और चारों दिशाओं (360 डिग्री) से तेजी से पढ़ा जा सकता है।"}, {'id': 90, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'DELNET (originally Delhi Library Network, later renamed Developing Library Network) was initiated in 1988 with the initial financial and technical support of which agency?', 'q_hi': 'डेलनेट (DELNET, मूल रूप से दिल्ली लाइब्रेरी नेटवर्क, बाद में डेवलपिंग लाइब्रेरी नेटवर्क) की शुरुआत 1988 में किस संस्था के प्रारंभिक वित्तीय एवं तकनीकी सहयोग से हुई थी?', 'options_en': ['Raja Rammohun Roy Library Foundation (RRRLF)', 'NISSAT (National Information System for Science and Technology)', 'UGC', 'National Archives of India'], 'options_hi': ['राजा राममोहन राय लाइब्रेरी फाउंडेशन (RRRLF)', 'निस्सैट (NISSAT', 'विश्वविद्यालय अनुदान आयोग (UGC)', 'राष्ट्रीय अभिलेखागार, नई दिल्ली'], 'answer': 'B', 'exp_en': "DELNET was initiated in 1988 with the support of NISSAT (Department of Scientific and Industrial Research, Govt. of India). It was officially registered as a society in 1992 and renamed 'Developing Library Network' in 2000, famous for its union catalog and inter-library loan (ILL) service.", 'exp_hi': "डेलनेट की स्थापना 1988 में निस्सैट (NISSAT, विज्ञान एवं प्रौद्योगिकी विभाग) के सहयोग से हुई थी। इसे 1992 में एक पंजीकृत सोसाइटी बनाया गया और वर्ष 2000 में इसका नाम बदलकर 'डेवलपिंग लाइब्रेरी नेटवर्क' कर दिया गया। यह केंद्रीय सूची (Union Catalogue) और अंतर-पुस्तकालय ऋण (ILL) हेतु विख्यात है।"}, {'id': 91, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "Recognized as India's first metropolitan library network conceptualized in 1986 by NISSAT/CSIR and launched in 1993, CALIBNET stands for:", 'q_hi': "निस्सैट (NISSAT) द्वारा 1986 में संकल्पित और 1993 में शुरू किया गया भारत का पहला महानगरीय पुस्तकालय नेटवर्क 'कैलिबनेट' (CALIBNET) किसका संक्षिप्त रूप है?", 'options_en': ['Calicut Library Network', 'Calcutta Library Network', 'Central Academic Library Network', 'Computerized Association of Libraries Network'], 'options_hi': ['कालीकट लाइब्रेरी नेटवर्क', 'कलकत्ता लाइब्रेरी नेटवर्क (Calcutta Library Network)', 'सेंट्रल एकेडमिक लाइब्रेरी नेटवर्क', 'कंप्यूटराइज्ड एसोसिएशन ऑफ लाइब्रेरीज नेटवर्क'], 'answer': 'B', 'exp_en': 'CALIBNET stands for Calcutta Library Network. Conceptualized in 1986 by NISSAT and launched in 1993, it holds the distinction of being the first metropolitan library network in India, aimed at interconnecting academic and research libraries in the Kolkata region.', 'exp_hi': "CALIBNET का पूर्ण रूप 'कलकत्ता लाइब्रेरी नेटवर्क' (Calcutta Library Network) है। 1986 में NISSAT द्वारा प्रायोजित और 1993 में प्रारंभ यह भारत का पहला महानगरीय पुस्तकालय नेटवर्क है जिसका उद्देश्य कोलकाता क्षेत्र के पुस्तकालयों को नेटवर्क से जोड़ना था।"}, {'id': 92, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "'ERNET' (Education and Research Network) was initiated in 1986 by the Department of Electronics (DoE), Government of India, with financial and technical assistance from which international organization?", 'q_hi': "भारत सरकार के इलेक्ट्रॉनिक्स विभाग (DoE) द्वारा 1986 में प्रारंभ किए गए 'एरनेट' (ERNET - Education and Research Network) को किस अंतरराष्ट्रीय संगठन से वित्तीय एवं तकनीकी सहायता प्राप्त हुई थी?", 'options_en': ['World Bank', 'United Nations Development Programme (UNDP)', 'UNESCO', 'International Monetary Fund (IMF)'], 'options_hi': ['विश्व बैंक', 'संयुक्त राष्ट्र विकास कार्यक्रम (UNDP)', 'यूनेस्को (UNESCO)', 'अंतरराष्ट्रीय मुद्रा कोष (IMF)'], 'answer': 'B', 'exp_en': 'ERNET was initiated in 1986 by the Department of Electronics (Government of India) with funding assistance from the United Nations Development Programme (UNDP). It pioneered the introduction of the Internet and networking in Indian academic and research institutions (IITs, IISc, NCST).', 'exp_hi': 'एरनेट (ERNET) की शुरुआत 1986 में भारत सरकार के इलेक्ट्रॉनिक्स विभाग द्वारा संयुक्त राष्ट्र विकास कार्यक्रम (UNDP) के सहयोग से की गई थी। इसने भारत के प्रमुख शैक्षणिक व अनुसंधान संस्थानों (IITs, IISc आदि) में इंटरनेट और कंप्यूटर नेटवर्किंग की नींव रखी।'}, {'id': 93, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'The Simple (Unqualified) Dublin Core metadata element set, standardized globally as ISO 15836 and NISO Z39.85, comprises how many core descriptive elements?', 'q_hi': 'सरल (Unqualified) डबलिन कोर मेटाडेटा तत्व सेट, जो अंतरराष्ट्रीय स्तर पर ISO 15836 और NISO Z39.85 के रूप में मानकीकृत है, में कुल कितने प्रमुख वर्णनात्मक तत्व शामिल हैं?', 'options_en': ['10 elements', '12 elements', '15 elements', '24 elements'], 'options_hi': ['10 तत्व', '12 तत्व', '15 तत्व (15 Elements)', '24 तत्व'], 'answer': 'C', 'exp_en': 'Simple Dublin Core comprises exactly 15 core elements: Title, Creator, Subject, Description, Publisher, Contributor, Date, Type, Format, Identifier, Source, Language, Relation, Coverage, and Rights. All elements are optional and repeatable.', 'exp_hi': 'सरल (अनक्वालिफाइड) डबलिन कोर में ठीक 15 बुनियादी मेटाडेटा तत्व होते हैं: Title, Creator, Subject, Description, Publisher, Contributor, Date, Type, Format, Identifier, Source, Language, Relation, Coverage और Rights। ये सभी तत्व वैकल्पिक और दोहराए जाने योग्य होते हैं।'}, {'id': 94, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "In Qualified Dublin Core metadata, what does the 'Dumb-Down Principle' dictate when an application system encounters an unfamiliar 'Element Refinement'?", 'q_hi': "क्वालिफाइड डबलिन कोर मेटाडेटा में, जब कोई एप्लिकेशन सिस्टम किसी अपरिचित 'एलिमेंट रिफाइनमेंट' (तत्व संशोधन) का सामना करता है, तो 'डंब-डाउन सिद्धांत' (Dumb-Down Principle) क्या निर्देश देता है?", 'options_en': ['The system must immediately crash and reject the record', 'The system can safely ignore the qualifier/refinement and treat the value as if it belongs to the broader, unqualified base element', 'The record must be automatically converted into a binary MARC format', 'All metadata fields must be deleted permanently'], 'options_hi': ['सिस्टम को क्रैश हो जाना चाहिए और रिकॉर्ड को अस्वीकार करना चाहिए', 'सिस्टम क्वालीफायर को सुरक्षित रूप से अनदेखा कर सकता है और उस मान को सामान्य मूल आधार तत्व मानकर संसाधित कर सकता है', 'रिकॉर्ड को स्वचालित रूप से बाइनरी मार्क फॉर्मेट में बदलना चाहिए', 'सभी मेटाडेटा फ़ील्ड्स को स्थायी रूप से हटा दिया जाना चाहिए'], 'answer': 'B', 'exp_en': "The 'Dumb-Down Principle' states that a client or search engine that does not understand a specific qualifier (element refinement like 'dateCreated' or 'abstract') can simply ignore the qualifier and treat the metadata value under the parent unqualified element ('Date' or 'Description') without breaking interoperability.", 'exp_hi': "'डंब-डाउन सिद्धांत' के अनुसार, यदि कोई सॉफ्टवेयर किसी विशिष्ट क्वालीफायर (जैसे Date के तहत 'dateCopyrighted') को नहीं समझता है, तो वह उस विशिष्टता को अनदेखा कर उसे सीधे उसके मूल आधार तत्व ('Date') के रूप में ग्रहण कर सकता है, जिससे डेटा खोज में कोई बाधा नहीं आती।"}, {'id': 95, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'In Qualified Dublin Core, qualifiers are formally divided into which two distinct categories?', 'q_hi': 'क्वालिफाइड डबलिन कोर (Qualified Dublin Core) में क्वालीफायर को औपचारिक रूप से किन दो विशिष्ट श्रेणियों में विभाजित किया गया है?', 'options_en': ['Primary qualifiers and Secondary qualifiers', 'Element Refinements and Encoding Schemes', 'Mandatory qualifiers and Optional qualifiers', 'Alpha qualifiers and Numeric qualifiers'], 'options_hi': ['प्राथमिक क्वालीफायर और द्वितीयक क्वालीफायर', 'तत्व संशोधन (Element Refinements) और एन्कोडिंग योजनाएं (Encoding Schemes)', 'अनिवार्य क्वालीफायर और वैकल्पिक क्वालीफायर', 'अल्फा क्वालीफायर और न्यूमेरिक क्वालीफायर'], 'answer': 'B', 'exp_en': "Qualified Dublin Core recognizes two types of qualifiers: (1) Element Refinements (which make an element's meaning narrower and more specific, e.g., 'dcterms:issued' refining 'date'), and (2) Encoding Schemes (which specify controlled vocabularies or formal syntax parsing, e.g., LCSH, DDC, or W3CDTF).", 'exp_hi': 'क्वालिफाइड डबलिन कोर में दो प्रकार के क्वालीफायर होते हैं: 1. तत्व संशोधन (Element Refinements) जो किसी तत्व के अर्थ को संकुचित/विशिष्ट बनाते हैं, तथा 2. एन्कोडिंग योजनाएं (Encoding Schemes) जो नियंत्रित शब्दावली या स्वरूप (जैसे DDC, LCSH, ISO 8601) को निर्दिष्ट करती हैं।'}, {'id': 96, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "In T.D. Wilson's landmark 1981 Model of Information-Seeking Behaviour, information need is posited not as a primary need, but as a secondary need arising out of which three fundamental human needs?", 'q_hi': 'टी. डी. विल्सन के 1981 के सूचना खोज व्यवहार मॉडल में, सूचना की आवश्यकता को प्राथमिक आवश्यकता नहीं माना गया है, बल्कि यह किन तीन मूलभूत मानवीय आवश्यकताओं से उत्पन्न होने वाली द्वितीयक आवश्यकता है?', 'options_en': ['Physical, Mechanical, and Electrical', 'Physiological, Affective (emotional), and Cognitive', 'Financial, Political, and Legal', 'Technical, Linguistic, and Historical'], 'options_hi': ['भौतिक, यांत्रिक और विद्युत आवश्यकताएं', 'शारीरिक (Physiological), भावनात्मक (Affective) और संज्ञानात्मक (Cognitive) आवश्यकताएं', 'वित्तीय, राजनीतिक और कानूनी आवश्यकताएं', 'तकनीकी, भाषाई और ऐतिहासिक आवश्यकताएं'], 'answer': 'B', 'exp_en': 'In his 1981 model, Tom D. Wilson asserted that information need is a secondary need that stems from basic human needs rooted in three categories: physiological (food, shelter, survival), affective/emotional (attitudes, security), and cognitive (intellectual understanding, problem-solving).', 'exp_hi': 'टी. डी. विल्सन (1981) ने स्पष्ट किया कि सूचना की आवश्यकता अपने आप में कोई प्राथमिक आवश्यकता नहीं है, बल्कि यह मानव की तीन बुनियादी आवश्यकताओं—शारीरिक (Physiological), भावनात्मक (Affective), और संज्ञानात्मक (Cognitive)—की संतुष्टि के क्रम में उत्पन्न होने वाली द्वितीयक आवश्यकता है।'}, {'id': 97, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "T.D. Wilson's 1996 Revised Model of Information Behaviour incorporated theories from other disciplines (Stress/Coping theory, Risk/Reward theory, Self-efficacy) and identified which four distinct modes of information-seeking?", 'q_hi': 'टी. डी. विल्सन के 1996 के संशोधित सूचना व्यवहार मॉडल में तनाव/मुकाबला सिद्धांत और जोखिम/इनाम सिद्धांत को शामिल किया गया; इस मॉडल में सूचना खोज के किन चार विशिष्ट तरीकों (Modes) की पहचान की गई?', 'options_en': ['Starting, Chaining, Browsing, and Extracting', 'Passive attention, Passive search, Active search, and Ongoing search', 'Selection, Exploration, Formulation, and Presentation', 'Direct, Indirect, Linear, and Non-linear'], 'options_hi': ['स्टार्टिंग, चेनिंग, ब्राउजिंग और एक्सट्रैक्टिंग', 'निष्क्रिय ध्यान (Passive attention), निष्क्रिय खोज, सक्रिय खोज और सतत खोज (Ongoing search)', 'चयन, अन्वेषण, सूत्रीकरण और प्रस्तुति', 'प्रत्यक्ष, अप्रत्यक्ष, रैखिक और गैर-रैखिक'], 'answer': 'B', 'exp_en': "Wilson's 1996 model expanded information acquisition into four behavioral modes: 1. Passive attention (absorbing information without active intention, e.g., viewing TV), 2. Passive search (accidental discovery), 3. Active search (actively seeking out specific information), and 4. Ongoing search (continuing to update knowledge in an area).", 'exp_hi': 'विल्सन के 1996 के मॉडल में सूचना प्राप्ति के चार तरीके बताए गए हैं: 1. निष्क्रिय ध्यान (Passive attention - अनपेक्षित रूप से सूचना ग्रहण करना), 2. निष्क्रिय खोज (Passive search), 3. सक्रिय खोज (Active search - उद्देश्यपूर्ण खोज), तथा 4. सतत खोज (Ongoing search - किसी क्षेत्र में निरंतर अद्यतन रहना)।'}, {'id': 98, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "Brenda Dervin's 'Sense-Making' methodology conceptualizes information seeking through a metaphorical triangle consisting of which three core components?", 'q_hi': "ब्रेंडा डरविन (Brenda Dervin) की 'सेंस-मेकिंग' (Sense-Making) पद्धति सूचना खोज को एक रूपक त्रिकोण के माध्यम से किन तीन प्रमुख घटकों में संकल्पित करती है?", 'options_en': ['Input, Processing, and Output', 'Situation, Gap, and Outcome (Bridge', 'Query, Document, and Relevance', 'Author, Publisher, and Reader'], 'options_hi': ['इनपुट, प्रोसेसिंग और आउटपुट', 'Use)', 'क्वेरी, प्रलेख और प्रासंगिकता', 'लेखक, प्रकाशक और पाठक'], 'answer': 'B', 'exp_en': 'Formulated in 1983 by Brenda Dervin, the Sense-Making metaphor describes a human being moving through time and space who stops at a moment of discontinuity: 1. Situation (the context in time/space), 2. Gap (the uncertainty, obstacle, or question faced), and 3. Bridge/Outcome (the sense made, help obtained, or information used to cross the gap).', 'exp_hi': 'ब्रेंडा डरविन (1983) का सेंस-मेकिंग मॉडल तीन घटकों के रूपक पर आधारित है: 1. स्थिति (Situation - पाठक की तत्कालीन परिस्थिति/समय-स्थान), 2. अंतराल या गैप (Gap - सूचना की कमी या असमंजस/प्रश्न), और 3. सेतु/परिणाम (Bridge / Outcome - उस अंतराल को पाटने हेतु प्राप्त सूचना और उसका उपयोग)।'}, {'id': 99, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': "The 'Seven Pillars of Information Literacy' model, which conceptualizes information literacy as a holistic continuum from basic library skills to synthesizing knowledge, was formulated in 1999 by:", 'q_hi': "'सूचना साक्षरता के सात स्तंभ' (Seven Pillars of Information Literacy) मॉडल, जो सूचना साक्षरता को बुनियादी कौशल से लेकर ज्ञान संश्लेषण तक एक समग्र निरंतरता के रूप में प्रस्तुत करता है, 1999 में किसके द्वारा प्रतिपादित किया गया था?", 'options_en': ['ALA (American Library Association)', 'SCONUL (Society of College, National and University Libraries, UK)', 'UNESCO Information for All Programme', 'IFLA Information Literacy Section'], 'options_hi': ['अमेरिकन लाइब्रेरी एसोसिएशन (ALA)', 'स्कोनुल (SCONUL, यूके)', 'यूनेस्को इन्फॉर्मेशन फॉर ऑल प्रोग्राम', 'इफ़्ला सूचना साक्षरता अनुभाग'], 'answer': 'B', 'exp_en': 'The Seven Pillars model was developed in 1999 (and revised in 2011) by the Society of College, National and University Libraries (SCONUL) in the United Kingdom. It provides a developmental framework for higher education information skills.', 'exp_hi': "सूचना साक्षरता का 'सेवन पिलर्स मॉडल' 1999 में यूनाइटेड किंगडम की 'सोसाइटी ऑफ कॉलेज, नेशनल एंड यूनिवर्सिटी लाइब्रेरीज' (SCONUL) द्वारा विकसित किया गया था (2011 में संशोधित)। यह उच्च शिक्षा में विद्यार्थियों के सूचना कौशल को सात स्तंभों में वर्गीकृत करता है।"}, {'id': 100, 'section_en': 'Part 1: Library & Information Science', 'section_hi': 'भाग 1: पुस्तकालय एवं सूचना विज्ञान', 'unit_en': 'Unit 5: Information Technology, Automation & User Studies', 'unit_hi': 'इकाई 5: सूचना प्रौद्योगिकी, पुस्तकालय स्वचालन एवं पाठक अध्ययन', 'q_en': 'In the SCONUL Seven Pillars of Information Literacy model, which pillar specifically represents the ability to *"construct effective search strategies for locating information and data"*, and which pillar deals with *"citing, referencing, and managing information ethically"*?', 'q_hi': "स्कोनुल (SCONUL) के सूचना साक्षरता के सात स्तंभ मॉडल में, कौन-सा स्तंभ विशेष रूप से 'सूचना खोजने हेतु प्रभावी रणनीति तैयार करने' की क्षमता को दर्शाता है, और कौन-सा स्तंभ 'नैतिक रूप से उद्धरण देने, संदर्भ प्रबंधन और साहित्यिक चोरी से बचने' से संबंधित है?", 'options_en': ["'Plan' and 'Manage' respectively", "'Identify' and 'Gather' respectively", "'Scope' and 'Present' respectively", "'Evaluate' and 'Identify' respectively"], 'options_hi': ["क्रमशः 'प्लान' (Plan) और 'मैनेज' (Manage)", "क्रमशः 'आइडेंटिफाई' और 'गैदर'", "क्रमशः 'स्कोप' और 'प्रेजेंट'", "क्रमशः 'इवैल्यूएट' और 'आइडेंटिफाई'"], 'answer': 'A', 'exp_en': "The SCONUL Seven Pillars sequence is: Identify $\\rightarrow$ Scope $\\rightarrow$ Plan $\\rightarrow$ Gather $\\rightarrow$ Evaluate $\\rightarrow$ Manage $\\rightarrow$ Present. The 'Plan' pillar represents the ability to construct search strategies, while the 'Manage' pillar covers the ethical storage, citing, and bibliographic management of data to avoid plagiarism.", 'exp_hi': "स्कोनुल के 7 स्तंभों का क्रम है: Identify, Scope, Plan, Gather, Evaluate, Manage, Present। इनमें 'Plan' (योजना) स्तंभ सूचना खोज की रणनीति बनाने से संबंधित है, जबकि 'Manage' (प्रबंधन) स्तंभ सूचना को नैतिक रूप से संग्रहीत करने, सही उद्धरण (Citations) देने और साहित्यिक चोरी से बचने से संबंधित है।"}]
